#!/usr/bin/env python3
"""The default figure set (Harry 2026-10-06: "a robust set of defaults ... go big"): about 245 figures. HEROES = 12
classes x 7 races x 2 genders = 168; about 44 townsfolk; about 21 common foes; 7 beasts and mounts; 4 large creatures.
One KIT per class (written once, worn by all 14 bodies) and one BODY reference plate per race and gender (14), so a
dwarf has the same proportions in every class and every paladin wears the same recognisable kit. Written with
what the pilot taught (README.md): no base in the mesh; the whole figure, whatever it holds included, inside an upright
cylinder 4 ft across for a creature on a 5-ft square (8.5 ft for a 10-ft square); held things upright, close, BROAD and
PALE so they read from the table camera; look-alikes named for animals; gaps between limbs, weapon and body; height in
feet. One style: the accepted pilot fighter plate is the style reference for the 14 body plates and for creatures; a
figure of a race takes that race's accepted body plate as its reference. One scale: a 6-ft human man is the yardstick.
Writes set/assets.json for gen.py (free Codex image route, the figure gate, BiRefNet matte).
    python3 set_spec.py && python3 gen.py set --group body --workers 5 --rerolls 1
    groups: body (14 references, first), canary (the slice judged before the bulk), hero, townsfolk, foe, beast, large
"""
import json
from pathlib import Path
HERE = Path(__file__).resolve().parent
REF = str(HERE / "inputs/fig-fighter.jpg")
BODY_DIR = HERE / "set/inputs"
HEAD_BODY = ("Create a new single asset in the Turnip Works house style (heroic hand-painted): a painted tabletop miniature FIGURE of {subject}.\n\n"
        "The supplied image is the BODY REFERENCE for this kind of person in this set: an undressed-for-adventure, plainly clothed figure of the same people and sex. The new figure must have the SAME body: "
        "the same height and build, the same head, hand and foot sizes, the same kind of skin, ears and features of its people, the same painting style, chunkiness, lighting, camera angle and flat blue background. "
        "It is a DIFFERENT individual with its own face and hair (described below), and it is dressed and equipped as described below instead of the reference's plain clothes.")
HEAD_KIN = ("Create a new single asset in the Turnip Works house style (heroic hand-painted): a painted tabletop miniature FIGURE of {subject}.\n\n"
        "The supplied image is ANOTHER MEMBER OF THE SAME WARBAND, already made. The new figure is the same kind of creature: the SAME body proportions, size, skin or bone colour and features, "
        "the same rough style of clothing and gear, the same painting style, lighting, camera angle and flat blue background, so the two stand side by side as one people. "
        "It is a DIFFERENT individual with DIFFERENT gear and a different stance, described below: its silhouette must be clearly different from the reference's.")
HEAD = ("Create a new single asset in the Turnip Works house style (heroic hand-painted): a painted tabletop miniature FIGURE of {subject}.\n\n"
        "The supplied image is ANOTHER FIGURE OF THE SAME SET, already made. The new figure must belong to the same set: the SAME painting style, the same chunkiness and level of detail, "
        "the same lighting, the same camera angle and the same flat blue background. It is a DIFFERENT character, described below: do not copy the reference's armour, colours, face or pose, "
        "and do NOT copy how far its sword and shield are held out to the sides.")
STYLE = """Geometry: heroic-scale tabletop miniature proportions: stout and chunky, slightly oversized head, hands, feet and held things; thick limbs; broad simple shapes; deep readable folds and plates rather than fine detail. Hands are simple chunky fists or mitten shapes. Every part thick enough to reconstruct as 3D geometry and to survive as a printed tabletop piece.
Held things: BROAD and chunky, never thin: wide blades, big heads on hammers, maces, staffs and spears, thick shafts. They are PALE or BRIGHT (bone-white wood, bright steel, cream, brass) against the clothes and skin, never plain dark wood-brown, so they show when the figure is seen small from above.
Finish: FULLY PAINTED in full colour, diffuse-first hand-painted game art with broad soft gradients, subtle brush texture, sparing painted edge highlights, low-frequency surface detail, mostly matte. A simple readable painted face.
Palette: rich but softened burgundy, moss green, ochre, cream, warm honey leather and wood, warm grey steel, used where they suit the figure. NO blue, teal or cyan anywhere on the figure (the background is a blue mask).
Avoid: grey unpainted primer, bare plastic or pewter, a bronze or stone statue look; photorealism, plastic toy gloss, strong reflections, black outlines, hard cel-shading bands, comic inking, flat vector art, anime or chibi proportions; thin fragile parts, loose straps, flying cloaks, long capes, banners, chains, feathers or hair strands sticking out; glow, magic effects, sparks, smoke; text, logos, emblems; multiple views, variants, a turnaround sheet or a grid in one image.

{pose}
NO BASE: no base, no ground disc, no plinth, no pedestal, no rock, no grass tuft, no patch of floor under the feet. The figure floats on the plain background, standing on nothing. No cast shadow and no dark blob under the feet.

Presentation for image-to-3D: exactly one complete figure, centered, three-quarter FRONT view (turned about 30 degrees, face and chest clearly visible) from very slightly above eye level, generous clear space around every edge, perfectly uniform solid chroma-blue background, no horizon, no floor plane, no cast shadow, neutral even lighting with no colored light casts and no dark shadowed side, no environment, no scenery, no additional objects or other figures. The blue background is a removable mask and must not reflect blue light onto the figure."""
POSE = {
 "hum": "Pose: ONE single full figure, the WHOLE body in frame from the top of the head to the soles of the feet, standing still and upright in a clear, stable, compact classic miniature pose (not a T-pose, not an action leap, not a crouch, not a wide stance). Feet shoulder-width apart with a clear gap between the legs, planted FLAT on the same level. COMPACT: the whole figure, with everything it holds, fits inside an upright cylinder {cyl} ft across; NOTHING is held out to the side at arm's length. Whatever it holds is held UPRIGHT and close, a hand's width in front of or beside the body, with clear background visible in the gap, so nothing fuses together. Elbows near the ribs.",
 "robe": "Pose: ONE single full figure, the WHOLE body in frame from the top of the head (or hat) to the soles of the shoes, standing still and upright in a clear, stable, compact classic miniature pose (not a T-pose, not an action leap). The robe or skirt hangs straight and ends at the ANKLES so both shoes show, flat on the same level; no train, no flying cloth. COMPACT: the whole figure, with everything it holds, fits inside an upright cylinder {cyl} ft across; NOTHING is held out to the side at arm's length. Whatever it holds is held UPRIGHT and close, a hand's width in front of or beside the body, with clear background visible in the gap, so nothing fuses together.",
 "quad": "Pose: ONE single whole animal in frame from nose to tail tip and from the top of its head to its feet, standing still and square on ALL FOUR legs in a calm, stable pose (not running, not rearing, not leaping). All four legs are separately and clearly visible, each one thick and sturdy, none hidden behind another, with clear background between them and under the belly; all four feet FLAT on the same level. COMPACT: the whole animal fits inside an upright cylinder {cyl} ft across: neck and head up, tail carried low and close, nothing stretched out.",
 "odd": "Pose: ONE single whole creature in frame, top to bottom, at rest in a clear, stable, compact pose, its underside flat on one level as if on an invisible floor. COMPACT: all of it fits inside an upright cylinder {cyl} ft across; nothing stretched far out to the side.",
}
NOT = ["any base, ground disc, plinth, pedestal, rock or patch of ground under the feet", "a cast shadow or dark blob under the feet",
       "the figure cropped by the frame anywhere (head, hat, weapon tip, feet, tail)", "limbs fused together or fused to the body with no gap where the spec asks for a gap",
       "a missing or broken held thing (something else carried as well is fine)", "more than one figure, or several views of the figure", "an unpainted grey, metal or stone statue look",
       "a weapon or arm held far out to the side at arm's length", "a rider, a second creature or scenery"]
F = []
CANARY = set()
def fig(id, group, subject, h, kind, design, desc, must=(), base=5, shaft=None, top=None, length=None, body=None, ref=None, prio=None, **meta):
    cyl = 4 if base == 5 else 8.5
    prompt = (HEAD_BODY if body else HEAD_KIN if ref else HEAD).format(subject=subject) + "\n\n" + STYLE.format(pose=POSE[kind].format(cyl=cyl)) + "\n\nSpecific design: " + design + "\n"
    common = {"hum": ["the whole figure head to toe, both feet visible", "a visible gap between the two legs"], "robe": ["the whole figure from head or hat to the hem, shoes or hem visible at the bottom"],
              "quad": ["the whole animal, nose to tail and head to feet", "FOUR separate legs all visible, with gaps between them"], "odd": ["the whole creature, nothing cut off"]}[kind]
    ht = {"body": h, "figure_top": top or h, "overall": top or h}
    if length: ht["length"] = length
    F.append({"id": id, "object": id, "family": "figures", "group": group, "source": "generate", "lane": "3d", "generation": "figure", "kind": kind, "subject": subject, "height_ft": ht, "shaft": shaft, "base_ft": base,
              "body": body, "canary": id in CANARY, "prio_set": prio, **meta,
              "prompt": prompt, "refs": [str(BODY_DIR / f"{body}.jpg")] if body else [str(BODY_DIR / f"{ref}.jpg")] if ref else [REF], "gate_refs": [], "gate": {"desc": desc, "must": common + list(must) + ["fully painted in colour"], "must_not": NOT}})
H = lambda who, ft: f"{who}, {ft} ft tall. "
ONE = lambda thing: [f"exactly one {thing}, complete end to end, clear of the body"]


# ------------------------------------------------------------------ the seven peoples: one body per people and sex
# height (ft), and the words that describe the body. A 6-ft human man is the yardstick for everything.
RACES = {
 "human":      {"m": (6.0, "a human man of average build"), "f": (5.6, "a human woman of average build")},
 "elf":        {"m": (5.9, "an elf man: slim and long-limbed, with long pointed ears and a narrow, fine-boned face"), "f": (5.7, "an elf woman: slim and long-limbed, with long pointed ears and a narrow, fine-boned face")},
 "dwarf":      {"m": (4.5, "a dwarf man: only 4.5 ft tall but nearly as broad as a human, with a barrel chest, short thick legs, big hands, a big nose and a full thick beard drawn as one solid chunky shape"),
                "f": (4.3, "a dwarf woman: only 4.3 ft tall but nearly as broad as a human, with a barrel chest, short thick legs, big hands, a big nose and thick braided hair (no beard)")},
 "small":      {"m": (3.1, "a small-folk man (halfling or gnome): only 3.1 ft tall, a small person with adult proportions, a slightly large head, a round nose, slightly pointed ears, curly hair and big feet in soft shoes; NOT a human child"),
                "f": (3.0, "a small-folk woman (halfling or gnome): only 3 ft tall, a small person with adult proportions, a slightly large head, a round nose, slightly pointed ears, curly hair and big feet in soft shoes; NOT a human child")},
 "orc":        {"m": (6.5, "an orc man: 6.5 ft tall and heavy, with grey-green skin, a heavy brow, a wide jaw with two lower tusks, pointed ears, a thick neck, broad sloping shoulders and long thick arms"),
                "f": (6.3, "an orc woman: 6.3 ft tall and powerfully built, with grey-green skin, a strong jaw with two small lower tusks, pointed ears and broad shoulders")},
 "tiefling":   {"m": (6.0, "a tiefling man: human-sized, with brick-red skin, two thick ram-like horns curving back close to the head, pointed ears, and a thick tail that hangs straight down close behind the legs"),
                "f": (5.8, "a tiefling woman: human-sized, with brick-red skin, two thick ram-like horns curving back close to the head, pointed ears, and a thick tail that hangs straight down close behind the legs")},
 "dragonborn": {"m": (6.5, "a dragonborn man: a 6.5-ft scaled, dragon-headed humanoid with a blunt reptile snout, a crest of short back-swept horns, bronze-gold scales, a thick neck, clawed hands and feet, NO wings and NO hair; a short thick tail hangs straight down close behind the legs"),
                "f": (6.3, "a dragonborn woman: a 6.3-ft scaled, dragon-headed humanoid, slimmer than the men, with a blunt reptile snout, a fan-like crest of short back-swept horns, copper-red scales, clawed hands and feet, NO wings and NO hair; a short thick tail hangs straight down close behind the legs")},
}
RNAME = {"human": "human", "elf": "elf", "dwarf": "dwarf", "small": "small-folk", "orc": "orc", "tiefling": "tiefling", "dragonborn": "dragonborn"}
SEX = {"m": "man", "f": "woman"}
# individual looks, dealt out in turn so fourteen fighters are fourteen people
LOOKS = {
 "human": ["warm brown skin and short black hair", "pale freckled skin and red hair", "olive skin and dark brown hair", "dark brown skin and close-cropped hair", "tan skin and sandy blond hair", "light skin and grey hair"],
 "elf": ["pale skin and long silver-white hair in one thick tail", "golden-tan skin and auburn hair", "light brown skin and black hair", "pale skin and honey-blond hair"],
 "dwarf": ["a red beard or red braids and ruddy skin", "a black beard or black braids and tan skin", "a grey beard or grey braids and weathered skin", "a blond beard or blond braids and pale skin"],
 "small": ["curly brown hair and rosy skin", "curly black hair and brown skin", "curly ginger hair and freckles", "curly grey hair and tan skin"],
 "orc": ["a black topknot", "a shaved head with one ochre war-paint stripe", "short dark hair and a scarred brow", "thick black braids"],
 "tiefling": ["black hair and brick-red skin", "deep plum-purple skin and white hair", "ash-grey skin and black hair", "dark red skin and a shaved head"],
 "dragonborn": ["bronze-gold scales", "copper-red scales", "cream-white scales", "moss-green scales with a cream throat"],
}
def body_id(r, s): return f"body-{r}-{s}"
for r, sexes in RACES.items():
    for s, (h, words) in sexes.items():
        W = words[0].upper() + words[1:]
        fig(body_id(r, s), "body", f"{words.split(':')[0]} in plain clothes (a body reference)", h, "hum",
            f"{W}; {h} ft tall. Plain, close-fitting clothes that show the body's build: a sleeveless cream tunic to the hip with a rope belt, ochre trousers to the ankle, simple shoes. "
            "Standing straight and relaxed, arms hanging a hand's width from the body, hands empty, looking forward. Nothing held, no hat, no cloak, no armour.",
            f"one {RNAME[r]} {SEX[s]} in a plain tunic and trousers, standing, empty-handed", ["empty hands (nothing held)"], route="reference-only", name=f"{RNAME[r].capitalize()} body reference ({SEX[s]})", race=r, gender=s)

# ------------------------------------------------------------------ the twelve class kits: written ONCE, worn by all 14 bodies
# kind, what makes the top taller than the head (ft at human size), the thin part measure.py tracks, the kit, what the gate must see.
# Told apart on purpose: sorcerer (no gear, a flame in the hand, flowing clothes) / warlock (dark, skull rod, chained tome) /
# wizard (robe, pointed hat, staff, spellbook) / bard (instrument, plume); fighter (plain steel, sword and round shield) /
# paladin (bright plate, cream cape and tabard, hammer, kite shield with a sun) / cleric (vestments over mail, mace, sun disc);
# ranger (bow, green hood up) / rogue (daggers, dark leather, mask); druid (crook, antlers, hides) / barbarian (bare arms,
# furs, great axe); monk (wraps, beads, bare hands).
KITS = {
 "barbarian": ("hum", 0, "axe", "BARBARIAN kit: bare arms and shoulders, a fur mantle lying flat on the shoulders, a broad leather harness (women: a hide chest wrap), a fur kilt with a big bone buckle, fur-wrapped boots, ochre war-paint stripes on the arms and face. "
    "BOTH hands hold a GREAT AXE upright in front of the body, butt at ground level between the feet: a thick bone-white shaft and ONE huge bright crescent blade beside the head, reaching just above the head. No shield, no armour plates.",
    "a bare-armed warrior in furs holding one great axe upright in front of the body", ["exactly one great axe with a big blade, complete end to end", "bare arms and furs, no plate armour"]),
 "bard": ("hum", 0.25, None, "BARD kit: flamboyant clothes: a wide soft ochre cap with ONE short, very thick cream plume lying back on it, a burgundy doublet with puffed cream-slashed sleeves, moss-green breeches, tall honey-brown boots, a short half-cape lying flat on the left shoulder only. "
    "Both hands hold a LUTE across the chest, close against the body, being played: a big pale cream round-bodied lute with a short thick neck angled up beside the left shoulder (no strings drawn). No weapon in the hands.",
    "a showily dressed musician in a plumed cap holding one lute close across the chest", ["one lute, complete, held against the body", "a cap with a plume"]),
 "cleric": ("hum", 0, None, "CLERIC kit: a knee-length mail shirt showing at the arms and knees under a long cream vestment-tabard with a wide burgundy border and a burgundy stole, a plain steel cap, sturdy boots. "
    "The RIGHT hand holds a MACE upright beside the shoulder: a thick pale shaft with a big round flanged brass head. The LEFT hand holds a big round brass SUN-DISC holy symbol (a plain disc with short thick rays, as large as the face) flat against the chest. No shield.",
    "a priest-warrior in cream vestments over mail holding one mace upright and a round brass sun disc at the chest", ["exactly one mace with a big head", "a round sun-disc symbol held at the chest", "cream vestments over mail"]),
 "druid": ("hum", 0.45, "crook", "DRUID kit: rough hides and leaves: a honey-brown hide tunic to the knee, a mantle of big overlapping moss-green leaves lying flat on the shoulders, a rope belt hung with one big pale gourd, bare shins and hide shoes. A headdress with two SHORT, very thick, blunt antlers (stubby, not branching). "
    "The RIGHT hand holds a CROOK upright close beside the body, foot at ground level: a THICK bone-white wooden staff as thick as the wrist with a big chunky spiral hook at the top, level with the antlers. The left hand is open at the side, close.",
    "a wild priest in hides and a leaf mantle with antlers or horns on the head, holding one thick pale crook-topped staff upright", ["exactly one crook-topped staff, complete end to end", "antlers or horns on the head", "hides and leaves, no metal armour"]),
 "fighter": ("hum", 0, "sword", "FIGHTER kit: plain, practical, unadorned warm grey steel armour: breastplate, shoulder plates and greaves over a padded burgundy tunic, an open-faced helmet so the face shows, a leather belt and boots. No cape, no tabard, no plume, no symbols. "
    "The RIGHT hand holds a broad straight SWORD upright in front of the right shoulder, bright steel blade pointing straight up, tip level with the top of the helmet. The LEFT arm holds a ROUND moss-green shield with a bright steel rim and boss CLOSE in front of the left hip, flat against the forearm.",
    "a soldier in plain grey steel armour holding one sword upright and one round green shield close to the body", ["exactly one sword, complete end to end", "one round shield", "plain armour without a cape or tabard"]),
 "monk": ("hum", 0, None, "MONK kit: no armour and no weapon: a sleeveless saffron-ochre wrap robe to the knee with a wide burgundy sash, cream cloth wrappings round the forearms and shins, BARE feet, a necklace of very big pale wooden prayer beads lying on the chest. Men have a shaved head; women wear their hair in one tight high topknot (peoples with horns, crests or beards keep them). "
    "A compact martial stance: both hands raised close in front of the chest, the right a fist, the left a flat open palm, elbows near the ribs.",
    "an unarmed, barefoot martial artist in a saffron wrap robe with big prayer beads, hands raised close to the chest", ["no weapon and no armour", "a wrap robe with a sash", "hands raised in front of the chest"]),
 "paladin": ("hum", 0, None, "PALADIN kit: SHINING polished pale steel full plate armour with bright brass trim, a long cream tabard with a brass border belted over it, a short cream cape hanging straight down the back (flat, not flying), no helmet but a broad brass circlet on the brow. "
    "The RIGHT hand holds a WARHAMMER upright beside the shoulder: a thick pale shaft with a big square bright steel head. The LEFT arm holds a tall cream KITE SHIELD with a brass rim and one big plain brass sun disc in its middle, CLOSE in front of the left side.",
    "a holy knight in bright plate with a cream tabard and cape, holding one warhammer upright and one tall kite shield with a sun disc", ["exactly one warhammer with a big head", "one tall kite shield", "bright plate armour with a cream tabard or cape"]),
 "ranger": ("hum", 0, "bow", "RANGER kit: a moss-green HOOD worn UP (the whole face visible) with a short shoulder cape lying flat, a honey-brown leather jerkin over an ochre shirt, moss-green trousers, tall soft boots, a fat cream quiver worn flat on the back with thick pale arrow ends showing over the right shoulder. "
    "The LEFT hand holds a LONGBOW upright close beside the body, its lower tip at ground level: a THICK pale bone-white bow as thick as the wrist, as tall as the shoulder, drawn as one solid chunky curved limb with NO string. The right hand rests on the belt.",
    "a hooded woodsman in green and leather holding one tall thick pale bow upright at the side, a quiver on the back", ["exactly one bow (a thick curved limb; no string needed), complete end to end", "a green hood", "no sword or shield"]),
 "rogue": ("hum", 0, None, "ROGUE kit: dark, close-fitting, quiet clothes: a charcoal-brown leather jacket and trousers, a dark burgundy HOOD worn UP and a burgundy cloth MASK over the nose and mouth so only the eyes show, soft boots, a belt with two fat pale pouches. "
    "Each hand holds a broad leaf-shaped DAGGER with a bright steel blade, points up, held at chest height close to the body, one beside each shoulder.",
    "a masked, hooded thief in dark leather holding two broad daggers upright close to the chest", ["exactly two daggers, each complete", "a hood and a mask over the lower face", "no bow, sword or shield"]),
 "sorcerer": ("hum", 0, None, "SORCERER kit: NO gear at all (no staff, no book, no hat, no weapon) and flowing, un-wizardly clothes: a long open sleeveless ochre-gold coat with a wide burgundy sash over a cream shirt, loose burgundy trousers gathered at the ankle, bare forearms with broad brass bangles, hair (or crest) swept up as if by wind, drawn as one solid chunky shape. "
    "A dramatic casting gesture, kept compact: the RIGHT hand is raised in front of the right shoulder, palm up, holding a big ball of bright orange-and-yellow FLAME as large as the head, drawn as ONE chunky solid teardrop shape (solid and opaque like carved wax, not glowing, no sparks). The LEFT hand is open, palm down, at waist height close to the body.",
    "a spellcaster in a flowing open coat with no hat, staff or book, holding one big solid ball of flame in a raised hand", ["one big ball of flame held in a raised hand", "no staff, no book and no pointed hat"]),
 "warlock": ("hum", 0, None, "WARLOCK kit: dark, sinister and NOT a wizard (no robe, no pointed hat, no long staff, no book in the hands): a ragged charcoal-black hooded leather COAT open down the front and ending at the knee, the deep HOOD worn UP so the face is in shadow but visible, dark trousers and tall black boots with a clear gap between the legs, a big brass EYE-shaped amulet on the chest, and a thick pale TOME bound in cream leather hanging closed at the LEFT hip on a short heavy brass chain. "
    "On the LEFT shoulder sits a small FAMILIAR: a fat little brick-red IMP as large as the head, with two stubby horns, folded wings and a curled tail, fused to the shoulder. The RIGHT hand is raised in front of the right shoulder holding a short SKULL-TOPPED ROD (as long as the forearm, not reaching the ground), and from the skull's top rises a big ball of eldritch fire painted sickly GREEN and yellow-green, drawn as ONE chunky solid spiky star shape as large as the head (solid and opaque like carved wax, not glowing).",
    "a sinister hooded figure in a dark knee-length coat with a small red imp on one shoulder, holding up a short skull rod topped with green fire, a book hanging at the hip", ["a hood", "a small imp or creature on the shoulder", "green fire or a skull rod held up", "no pointed hat"]),
 "wizard": ("robe", 0.9, "staff", "WIZARD kit: a tall POINTED wide-brimmed burgundy hat with a stout, slightly bent cone; a heavy burgundy robe with moss-green trim and an ochre rope belt, ending at the ankles (peoples with horns wear the hat between them). "
    "The RIGHT hand holds a STAFF upright close beside the body, a hand's width from the robe, foot at ground level: a THICK bone-white staff as thick as the wrist topped with a big chunky cream crystal block as large as a fist, level with the hat brim. The LEFT arm holds a big pale cream SPELLBOOK against the chest.",
    "a robed wizard in a tall pointed hat holding one thick pale staff upright and one big book against the chest", ["exactly one staff, complete end to end", "a tall pointed hat, complete", "one big book"]),
}
SRD_CLASS = {"barbarian": ["berserker", "tribal warrior"], "bard": [], "cleric": ["priest", "acolyte"], "druid": ["druid"], "fighter": ["veteran", "guard", "gladiator"], "monk": [],
             "paladin": ["knight"], "ranger": ["scout"], "rogue": ["spy", "assassin", "thug"], "sorcerer": ["mage"], "warlock": ["cult fanatic", "mage"], "wizard": ["mage", "archmage"]}
RTAGS = {"human": ["human"], "elf": ["elf", "half-elf"], "dwarf": ["dwarf"], "small": ["halfling", "gnome", "small folk"], "orc": ["orc", "half-orc"], "tiefling": ["tiefling"], "dragonborn": ["dragonborn"]}
CLASSES = list(KITS)
# the canary slice, judged before the bulk: every class as a human (genders alternating), every people as a fighter, six more for mix
CANARY.update({f"hero-{c}-human-{'mf'[i % 2]}" for i, c in enumerate(CLASSES)})
CANARY.update({"hero-fighter-elf-f", "hero-fighter-dwarf-m", "hero-fighter-small-f", "hero-fighter-orc-m", "hero-fighter-tiefling-f", "hero-fighter-dragonborn-m", "hero-fighter-human-f",
               "hero-paladin-dwarf-f", "hero-wizard-small-m", "hero-rogue-tiefling-m", "hero-sorcerer-dragonborn-f", "hero-ranger-elf-m", "hero-barbarian-orc-f"})
CANARY.update({"town-innkeeper-m", "town-guard-f", "town-constable", "town-cook", "town-child-girl"})
n = 0
for c in CLASSES:
    kind, extra, shaft, kit, desc, must = KITS[c]
    for r, sexes in RACES.items():
        for s, (h, words) in sexes.items():
            look = LOOKS[r][n % len(LOOKS[r])]; n += 1
            top = round(h + extra * h / 6, 2) if extra else None
            W = words[0].upper() + words[1:]
            tall = f"{h} ft tall" + (f" ({top} ft to the top of the {'hat' if c == 'wizard' else 'antlers' if c == 'druid' else 'plume'})" if top else "")
            fig(f"hero-{c}-{r}-{s}", "hero", f"a {RNAME[r]} {c}, a {SEX[s]}", h, kind, f"{W}; {tall}; this one has {look}. Everything is sized to this body. {kit}",
                f"one {RNAME[r]} {SEX[s]}: {desc}", must, shaft=shaft, top=top, body=body_id(r, s),
                name=f"{RNAME[r].capitalize()} {c} ({SEX[s]})", race=r, gender=s, cls=c, tags=[c, "hero", "player character"] + RTAGS[r] + [SEX[s]], srd=SRD_CLASS[c])

# ------------------------------------------------------------------ townsfolk (about 44): a role, a silhouette, ONE clear prop held broad and pale
g = "townsfolk"
TOWN_SRD = {"guard": ["guard"], "soldier": ["guard", "veteran"], "captain": ["veteran", "knight"], "noble": ["noble"], "priest": ["priest", "acolyte"], "commoner": ["commoner"], "thief": ["spy", "thug"], "scholar": ["mage"], "hunter": ["scout"]}
def town(id, r, s, role, who, kit, desc, must=(), kind="hum", h=None, shaft=None, top=None, body=True, srd=("commoner",), tags=(), prio=None):
    hh, words = RACES[r][s]; h = h or hh
    fig(f"town-{id}", g, role, h, kind, f"{words[0].upper() + words[1:]}; {h} ft tall; {who}. {kit}", f"one {RNAME[r]} {SEX[s] if h > 4.6 or r in ('dwarf', 'small') else 'child'}: {desc}", must, shaft=shaft, top=top, body=body_id(r, s) if body else None, prio=prio,
        name=f"{role[0].upper() + role[1:]} ({RNAME[r]} {SEX[s]})".replace("A ", "", 1).replace("An ", "", 1), race=r, gender=s, cls=id.split("-")[0] if not id.split("-")[0] in RACES else id.split("-", 1)[1], tags=[RNAME[r], SEX[s], "townsfolk", "npc"] + RTAGS[r] + list(tags) + id.split("-"), srd=list(srd))
P = lambda thing: [f"one {thing}"]
